import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from the vendor's logo.
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml"
  }
];

import {
  accountRouter,
  decodeJson,
  defineApp,
  defineProvider,
  number,
  oauth2,
  object,
  router,
  secrets,
  string,
  withApprovals,
} from "apps";
import { always } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";

const User = object({ id: number(), username: string(), web_url: string() });

const gitlab = defineProvider({
  name: "GitLab",
  hosts: ["gitlab.com"],
  site: { label: "GitLab instance URL", origin: "https://gitlab.com", defaultOrigin: true },
  auth: {
    token: secrets({
      label: "Access token",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
    // The user creates an OAuth application at gitlab.com; the connect page asks for its client.
    oauth: oauth2({
      authorizationUrl: "https://gitlab.com/oauth/authorize",
      tokenUrl: "https://gitlab.com/oauth/token",
      revocationUrl: "https://gitlab.com/oauth/revoke",
      tokenEndpointAuthMethod: "client_secret_post",
      scopes: ["api", "read_user"],
    }),
  },
  async health({ account, fetch, signal }) {
    const site = account.site ?? "https://gitlab.com";
    const headers: Record<string, string> =
      account.method === "oauth"
        ? { Authorization: `Bearer ${account.fields.access_token}` }
        : { "PRIVATE-TOKEN": account.fields.token };
    const response = await fetch(new URL("/api/v4/user", site), { signal, headers });
    const me = await decodeJson(response, User);
    return { accountInfo: { externalId: String(me.id), username: me.username, profileUrl: me.web_url } };
  },
});

const description =
  "Projects, merge requests, issues, pipelines, repositories, groups, users and the REST API on GitLab.com or a self-managed instance.";

export default defineApp(
  { user: { accounts: { gitlab: gitlab.many() } }, icons },
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      await accountRouter(
        user?.accounts.gitlab ?? [],
        (account) => {
          const site = account.site ?? "https://gitlab.com";
          const documentUrl = new URL(
            "/gitlab-org/gitlab/-/raw/master/doc/api/openapi/openapi_v3.yaml",
            site,
          ).href;
          return withApprovals(
            liveOpenapiRouter({
              ...options,
              source: { ...options.source, url: documentUrl },
              allowedOrigin: site,
              baseUrl: site,
              cache,
              fetch,
              signal,
              account,
            }),
            (tool) => (tool.kind === "mutation" ? always() : undefined),
          );
        },
        { signal },
      ),
      { title: "GitLab", description, icons },
    ),
  }),
);

import type { OpenapiToolNamesOptions } from "apps/openapi";

// GitLab's own generated OpenAPI 3.0 document. Operations accept http bearer, oauth2 or the
// PRIVATE-TOKEN apiKey header.
export const options = {
  source: { url: "https://gitlab.com/gitlab-org/gitlab/-/raw/master/doc/api/openapi/openapi_v3.yaml" },
  allowedOrigin: "https://gitlab.com",
  baseUrl: "https://gitlab.com",
  securitySchemes: {
    apiKey: { type: "apiKey", name: "PRIVATE-TOKEN", in: "header" },
    http: { type: "http", scheme: "bearer" },
  },
  fallbackSecurity: [{ apiKey: [] }],
  methods: {
    token: [{ scheme: "apiKey", field: "token", part: "value", prefix: "" }],
    oauth: [{ scheme: "http", field: "access_token", part: "value", prefix: "" }],
  },
  oauth: [],
} satisfies OpenapiToolNamesOptions;

{
  "name": "@executor.sh/gitlab",
  "description": "Projects, merge requests, issues, pipelines, repositories, groups, users and the rest of the GitLab REST API.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "GitLab"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.1"
  }
}
